const MAX_RETRIES = 3;

export class JobQueue {
  private concurrency: number;
  private running = 0;
  private pending: (() => Promise<void>)[] = [];
  private idleWaiters: (() => void)[] = [];

  constructor(concurrency: number) {
    if (!(concurrency >= 1)) throw new RangeError("concurrency must be >= 1");
    this.concurrency = concurrency;
  }

  /** Resolves with the job's result, or rejects with its last error once retries are exhausted. */
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => attempt(job).then(resolve, reject));
      this.next();
    });
  }

  /** Resolves once nothing is running or waiting. */
  onIdle(): Promise<void> {
    if (this.running === 0 && this.pending.length === 0) return Promise.resolve();
    return new Promise((resolve) => this.idleWaiters.push(resolve));
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      this.running++;
      this.pending.shift()!().finally(() => {
        this.running--;
        this.next();
      });
    }
    if (this.running === 0) for (const resolve of this.idleWaiters.splice(0)) resolve();
  }
}

// ponytail: retries immediately and holds its concurrency slot; add backoff here if jobs hit rate-limited services
async function attempt<T>(job: () => Promise<T>): Promise<T> {
  for (let failures = 0; ; failures++) {
    try {
      return await job();
    } catch (err) {
      if (failures >= MAX_RETRIES) throw err;
    }
  }
}

import assert from "node:assert/strict";
import { JobQueue } from "./queue.ts";

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

// concurrency limit + onIdle
{
  const q = new JobQueue(2);
  let active = 0, peak = 0, done = 0;
  for (let i = 0; i < 6; i++) {
    q.add(async () => {
      peak = Math.max(peak, ++active);
      await sleep(10);
      active--;
      done++;
    });
  }
  await q.onIdle();
  assert.equal(peak, 2);
  assert.equal(done, 6);
  await q.onIdle(); // already idle resolves immediately
}

// succeeds on the third retry
{
  const q = new JobQueue(1);
  let calls = 0;
  const result = await q.add(async () => {
    if (++calls < 4) throw new Error("flaky");
    return "ok";
  });
  assert.equal(result, "ok");
  assert.equal(calls, 4);
}

// gives up after 1 try + 3 retries, and the queue keeps going
{
  const q = new JobQueue(1);
  let calls = 0;
  const failed = q.add(async () => {
    calls++;
    throw new Error("always");
  });
  const after = q.add(async () => "next");
  await assert.rejects(failed, /always/);
  assert.equal(calls, 4);
  assert.equal(await after, "next");
  await q.onIdle();
}

